document.addEventListener("DOMContentLoaded",function(){const e=document.querySelector(".nav__toggle"),t=document.querySelector(".nav__menu"),o=document.querySelector(".nav");if(!e||!t)return;function i(){e.setAttribute("aria-expanded","true"),t.classList.add("active");const n=t.querySelector(".nav__link");n&&n.focus()}function n(){e.setAttribute("aria-expanded","false"),t.classList.remove("active"),e.focus()}function s(){return e.getAttribute("aria-expanded")==="true"}e.addEventListener("click",function(){s()?n():i()}),document.addEventListener("keydown",function(e){e.key==="Escape"&&s()&&n()}),document.addEventListener("click",function(e){s()&&!o.contains(e.target)&&n()}),t.querySelectorAll(".nav__link").forEach(function(e){e.addEventListener("click",function(){window.innerWidth<=768&&n()})})})